F={'sh':'shelter','cl':'clothing and adornment','fs':'food and storage','to':'tools','rw':'record and writing','ex':'exchange and value','rb':'ritual and belief','rd':'rule and display','wa':'war','pm':'play and music','ca':'care and access','tr':'transport'}
S={'L':'living-community','I':'Indigenous-community','S':'sacred','F':'funerary','A':'ancestral','H':'human-flow','C':'conflict-looting'}
SRC={'MET':'Met Open Access (CC0)','CMA':'Cleveland Museum of Art Open Access (CC0)','AIC':'Art Institute of Chicago (CC0 images)','YUAG':'Yale University Art Gallery (public-domain images)','SI':'Smithsonian Open Access (CC0 where flagged; check per item)','WC':'Wikimedia Commons','EUR':'Europeana','BM':'British Museum collection online (view; licence per image)','PRM':'Pitt Rivers Museum collections online (view)','MQB':'musée du quai Branly collections online (view)','RIJ':'Rijksmuseum (CC0)','WEL':'Wellcome Collection (CC BY)','TP':'Te Papa Collections Online (some CC BY)','AKL':'Auckland Museum Collections Online (many CC BY)','LOC':'Library of Congress (public domain items)','IA':'Internet Archive (public-domain ethnographies; read critically)','UN':'UNESCO ICH pages (text; status to verify)','LC':'Local Contexts Notices and Labels (protocol)','WMN':'Wereldmuseum / NMVW collections online (view; licence per item)','BRK':'Brooklyn Museum (some CC BY)','HAR':'Himalayan Art Resources (view)','AIATSIS':'AIATSIS collections and ethics code (protocol)','HOR':'Horniman Museum collections online (view)','MIA':'Minneapolis Institute of Art (public-domain images)'}
def r(name,other,world,subs,s,e,dn,sig,mats,objs,funcs,mus,leaves,sens,src,tier,units,conf,notes=''):
    return dict(name=name,other_names=other,kind='community',family='People',world=world,sub_regions=subs,start=s,end=e,date_note=dn,making_significance=sig,materials_techniques=mats,object_types=objs,functions='; '.join(F[x] for x in funcs.split()),defined_by='the community'+('; ethnographic and museum usage' if mus else ''),leaves_out=leaves,sensitivity='; '.join(S[c] for c in sens if c in S) if sens else 'none',free_sources='; '.join(SRC.get(x.strip(),x.strip()) for x in src.split('|')),tier=tier,units=units,confidence=conf,notes=notes)
